input.command:
cd /root/.claude/projects/-root/; python3 - <<'EOF'
import json,glob
for fn in glob.glob('*.jsonl'):
    if fn.startswith('238c8842'): continue
    try:
        for line in open(fn,errors='ignore'):
            if 'qm stop' not in line and 'qm destroy' not in line: continue
            try: o=json.loads(line)
            except: continue
            ts=o.get('timestamp','')
            if not ts.startswith('2026-09-06T0'): continue
            s=json.dumps(o)
            import re
            for m in re.findall(r'"command":"((?:[^"\\]|\\.)*)"',s):
                if 'qm stop' in m or 'qm destroy' in m:
                    print(f"{ts}  [{fn[:8]}]  {m[:150]}")
    except Exception as e: pass
EOF

